begin;
    with j as (select * from jsonb_to_recordset($law7v008$[{"code_id":"GK_RF","article_number":"234","version_date":"1994-11-30","article_text":"Право собственности на недвижимое и иное имущество, подлежащее государственной регистрации, возникает у лица, приобретшего это имущество в силу приобретательной давности, с момента такой регистрации.","article_title":"Статья 234. Приобретательная давность","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a2a60728ea23153a5d9cb93aeba40e119bff529c415e412025fbfba2946e446e"},{"code_id":"GK_RF","article_number":"235","version_date":"1994-11-30","article_text":"1. Право собственности прекращается при отчуждении собственником своего имущества другим лицам, отказе собственника от права собственности, гибели или уничтожении имущества и при утрате права собственности на имущество в иных случаях, предусмотренных законом.\n\n2. Принудительное изъятие у собственника имущества не допускается, кроме случаев, когда по основаниям, предусмотренным законом, производятся:\n\n1) обращение взыскания на имущество по обязательствам (статья 237);\n\n2) отчуждение имущества, которое в силу закона не может принадлежать данному лицу (статья 238);\n\n3) отчуждение недвижимого имущества в связи с изъятием земельного участка ввиду его ненадлежащего использования (статья 239); (В редакции Федерального закона от 31.12.2014 № 499-ФЗ)\n\n31) отчуждение объекта незавершенного строительства в связи с прекращением действия договора аренды земельного участка, находящегося в государственной или муниципальной собственности (статья 2391); (Дополнение подпунктом - Федеральный закон от 23.06.2014 № 171-ФЗ)\n\n32) отчуждение недвижимого имущества в связи с принудительным отчуждением земельного участка для государственных или муниципальных нужд (изъятием земельного участка для государственных или муниципальных нужд (статья 2392);  (Дополнение подпунктом - Федеральный закон от 31.12.2014 № 499-ФЗ)\n\n4) выкуп бесхозяйственно содержимых культурных ценностей, домашних животных (статьи 240 и 241);\n\n5) реквизиция (статья 242);\n\n6) конфискация (статья 243);\n\n7) отчуждение имущества в случаях, предусмотренных статьей 2392, пунктом 4 статьи 252, пунктом 2 статьи 272, статьями 282, 285, 293, пунктами 4 и 5 статьи 1252 настоящего Кодекса; (В редакции федеральных законов от 18.12.2006 № 231-ФЗ; от 31.12.2014 № 499-ФЗ)\n\n8) обращение по решению суда в доход Российской Федерации имущества, в отношении которого не представлены в соответствии с законодательством Российской Федерации о противодействии коррупции доказательства его приобретения на законные доходы; (Дополнение подпунктом - Федеральный закон от 03.12.2012 № 231-ФЗ)\n\n9) обращение по решению суда в доход Российской Федерации денег, ценностей, иного имущества и доходов от них, в отношении которых в соответствии с законодательством Российской Федерации о противодействии терроризму лицом не представлены сведения, подтверждающие законность их приобретения. (Дополнение подпунктом - Федеральный закон от 02.11.2013 № 302-ФЗ)\n\nПо решению собственника в порядке, предусмотренном законами о приватизации, имущество, находящееся в государственной или муниципальной собственности, отчуждается в собственность граждан и юридических лиц.\n\nОбращение в государственную собственность имущества, находящегося в собственности граждан и юридических лиц (национализация), производится на основании закона с возмещением стоимости этого имущества и других убытков в порядке, установленном статьей 306 настоящего Кодекса.","article_title":"Статья 235. Основания прекращения права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"46ed3a77df695ac6b311a175df53597ef8c895e8893de5822bd2129ca6d35b60"},{"code_id":"GK_RF","article_number":"236","version_date":"1994-11-30","article_text":"Гражданин или юридическое лицо может отказаться от права собственности на принадлежащее ему имущество, объявив об этом либо совершив другие действия, определенно свидетельствующие о его устранении от владения, пользования и распоряжения имуществом без намерения сохранить какие-либо права на это имущество.\n\nОтказ от права собственности не влечет прекращения прав и обязанностей собственника в отношении соответствующего имущества до приобретения права собственности на него другим лицом.","article_title":"Статья 236. Отказ от права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5f7a3e1d962fc1949122f96b934dde69df58acd448b4c9eaf428c66b9b9f7c73"},{"code_id":"GK_RF","article_number":"237","version_date":"1994-11-30","article_text":"1. Изъятие имущества путем обращения взыскания на него по обязательствам собственника производится на основании решения суда, если иной порядок обращения взыскания не предусмотрен законом или договором.\n\n2. Право собственности на имущество, на которое обращается взыскание, прекращается у собственника с момента возникновения права собственности на изъятое имущество у лица, к которому переходит это имущество.","article_title":"Статья 237. Обращение взыскания на имущество по обязательствам собственника","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"efc8713b4ca372d8d353033507c6e8dcbd596794901179a696a8c7b020fcc403"},{"code_id":"GK_RF","article_number":"238","version_date":"1994-11-30","article_text":"1. Если по основаниям, допускаемым законом, в собственности лица оказалось имущество, которое в силу закона не может ему принадлежать, это имущество должно быть отчуждено собственником в течение года с момента возникновения права собственности на имущество, если законом не установлен иной срок.","article_title":"Статья 238. Прекращение права собственности лица на имущество, которое не может ему принадлежать","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2a4eefe1bdd208e5637524cff385ed84a3bbc899883dda393bd20ef3b74c0982"},{"code_id":"GK_RF","article_number":"239","version_date":"1994-11-30","article_text":"Абзац. (Утратил силу - Федеральный закон от 31.12.2014 № 499-ФЗ)","article_title":"Статья 239. Отчуждение недвижимого имущества в связи с изъятием участка, на котором оно находится","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1d801b10cdd727660fe29d19bdc6a620da1146e9b891e91430c2465e15a2dae3"},{"code_id":"GK_RF","article_number":"239.1","version_date":"1994-11-30","article_text":"1. Если иное не предусмотрено законом, в случае прекращения действия договора аренды земельного участка, находящегося в государственной или муниципальной собственности и предоставленного по результатам аукциона, объекты незавершенного строительства, расположенные на таком земельном участке, могут быть изъяты у собственника по решению суда путем продажи с публичных торгов.\n\nПорядок проведения публичных торгов по продаже объектов незавершенного строительства устанавливается Правительством Российской Федерации.\n\n2. Требование в суд о продаже объекта незавершенного строительства с публичных торгов вправе заявить исполнительный орган государственной власти или орган местного самоуправления, уполномоченные на распоряжение земельным участком, который находится в государственной или муниципальной собственности и на котором расположен этот объект.\n\n3. Требование о продаже объекта незавершенного строительства не подлежит удовлетворению, если собственник этого объекта докажет, что нарушение срока строительства объекта связано с действиями (бездействием) органов государственной власти, органов местного самоуправления или лиц, осуществляющих эксплуатацию сетей инженерно-технического обеспечения, к которым должен быть подключен (технологически присоединен) объект.\n\n4. Начальная цена продажи объекта незавершенного строительства определяется на основании оценки его рыночной стоимости.\n\nЕсли публичные торги по продаже объекта незавершенного строительства признаны несостоявшимися, такой объект может быть приобретен в государственную или муниципальную собственность по начальной цене этого объекта в течение двух месяцев со дня признания торгов несостоявшимися.\n\n5. Средства, вырученные от продажи объекта незавершенного строительства с публичных торгов либо приобретения такого объекта в государственную или муниципальную собственность, выплачиваются бывшему собственнику объекта за вычетом расходов на подготовку и проведение публичных торгов.\n\n6. Правила настоящей статьи применяются также в случае прекращения действия договора аренды земельного участка, находящегося в государственной или муниципальной собственности, который заключен без проведения торгов в целях завершения строительства объекта незавершенного строительства, при условии, что строительство этого объекта не было завершено.\n\n(Дополнение статьей - Федеральный закон от 23.06.2014 № 171-ФЗ)","article_title":"Статья 239.1. Отчуждение объекта незавершенного строительства, расположенного на земельном участке, находящемся в государственной или муниципальной собственности, в связи с прекращением действия договора аренды такого земельного участка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"dc7366060c18fe681af5155bb7151394b11e089afc1109f90a43bf343c487f2e"},{"code_id":"GK_RF","article_number":"239.2","version_date":"1994-11-30","article_text":"(Дополнение статьей - Федеральный закон от 31.12.2014 № 499-ФЗ)","article_title":"Статья 239.2. Отчуждение недвижимого имущества в связи с изъятием земельного участка для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8f840809c8f113b046ab71ed57bd6533ea11cf68b676e6ec627a5f9257356fe9"},{"code_id":"GK_RF","article_number":"24","version_date":"1994-11-30","article_text":"Гражданин отвечает по своим обязательствам всем принадлежащим ему имуществом, за исключением имущества, на которое в соответствии с законом не может быть обращено взыскание.\n\nПеречень имущества граждан, на которое не может быть обращено взыскание, устанавливается гражданским процессуальным законодательством.","article_title":"Статья 24. Имущественная ответственность гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9b14c0a717df2aedc142535701d5c4eebfcaeefd61dd4b9eb99c055a5af46f6e"},{"code_id":"GK_RF","article_number":"240","version_date":"1994-11-30","article_text":"В случаях, когда собственник культурных ценностей, отнесенных в соответствии с законом к особо ценным и охраняемым государством, бесхозяйственно содержит эти ценности, что грозит утратой ими своего значения, такие ценности по решению суда могут быть изъяты у собственника путем выкупа государством или продажи с публичных торгов.\n\nПри выкупе культурных ценностей собственнику возмещается их стоимость в размере, установленном соглашением сторон, а в случае спора - судом. При продаже с публичных торгов собственнику передается вырученная от продажи сумма за вычетом расходов на проведение торгов, а также стоимости восстановительных работ в отношении объекта культурного наследия, или стоимости мероприятий, необходимых для сохранения объекта археологического наследия, указанных в статье 40 Федерального закона от 25 июня 2002 года № 73-ФЗ \"Об объектах культурного наследия (памятниках истории и культуры) народов Российской Федерации\". (В редакции Федерального закона от 22.10.2014 № 315-ФЗ)","article_title":"Статья 240. Выкуп бесхозяйственно содержимых культурных ценностей","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37d916ddacf110ae6be514f6fb4d640a222768a773b73dac3e5e11a5d09e6237"},{"code_id":"GK_RF","article_number":"241","version_date":"1994-11-30","article_text":"В случаях, когда собственник домашних животных обращается с ними в явном противоречии с установленными на основании закона правилами и принятыми в обществе нормами гуманного отношения к животным, эти животные могут быть изъяты у собственника путем их выкупа лицом, предъявившим соответствующее требование в суд. Цена выкупа определяется соглашением сторон, а в случае спора - судом.","article_title":"Статья 241. Выкуп домашних животных при ненадлежащем обращении с ними","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"458f71f6323a8af34027a03ed6d72df83b79cfed6310180819359ca69a6eb551"},{"code_id":"GK_RF","article_number":"242","version_date":"1994-11-30","article_text":"1. В случаях стихийных бедствий, аварий, эпидемий, эпизоотий и при иных обстоятельствах, носящих чрезвычайный характер, имущество в интересах общества по решению государственных органов может быть изъято у собственника в порядке и на условиях, установленных законом, с выплатой ему стоимости имущества (реквизиция).\n\n2. Оценка, по которой собственнику возмещается стоимость реквизированного имущества, может быть оспорена им в суде.\n\n3. Лицо, имущество которого реквизировано, вправе при прекращении действия обстоятельств, в связи с которыми произведена реквизиция, требовать по суду возврата ему сохранившегося имущества.","article_title":"Статья 242. Реквизиция","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"61cdffcd28232156463ce72a3c0d2ef1e787c244f61a91f681d8d432fb6dc1d1"},{"code_id":"GK_RF","article_number":"243","version_date":"1994-11-30","article_text":"1. В случаях, предусмотренных законом, имущество может быть безвозмездно изъято у собственника по решению суда в виде санкции за совершение преступления или иного правонарушения (конфискация).\n\n(Дополнение абзацем - Федеральный закон от 24.07.2023 № 351-ФЗ)","article_title":"Статья 243. Конфискация","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7cc5728fcbf4b1458c12555717cbafe8cf86d75ac463f4a13ee951ce65b99368"},{"code_id":"GK_RF","article_number":"244","version_date":"1994-11-30","article_text":"1. Имущество, находящееся в собственности двух или нескольких лиц, принадлежит им на праве общей собственности.\n\n2. Имущество может находиться в общей собственности с определением доли каждого из собственников в праве собственности (долевая собственность) или без определения таких долей (совместная собственность).\n\n3. Общая собственность на имущество является долевой, за исключением случаев, когда законом предусмотрено образование совместной собственности на это имущество.\n\n4. Общая собственность возникает при поступлении в собственность двух или нескольких лиц имущества, которое не может быть разделено без изменения его назначения (неделимые вещи) либо не подлежит разделу в силу закона.\n\nОбщая собственность на делимое имущество возникает в случаях, предусмотренных законом или договором.\n\n5. По соглашению участников совместной собственности, а при недостижении согласия по решению суда на общее имущество может быть установлена долевая собственность этих лиц.","article_title":"Статья 244. Понятие и основания возникновения общей собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"baf79a5372e3172854783daf297b35461c6c113d492b8003823cbb7fb3e0fcba"},{"code_id":"GK_RF","article_number":"245","version_date":"1994-11-30","article_text":"1. Если доли участников долевой собственности не могут быть определены на основании закона и не установлены соглашением всех ее участников, доли считаются равными.\n\n2. Соглашением всех участников долевой собственности может быть установлен порядок определения и изменения их долей в зависимости от вклада каждого из них в образование и приращение общего имущества.\n\n3. Участник долевой собственности, осуществивший за свой счет с соблюдением установленного порядка использования общего имущества неотделимые улучшения этого имущества, имеет право на соответствующее увеличение своей доли в праве на общее имущество.\n\nОтделимые улучшения общего имущества, если иное не предусмотрено соглашением участников долевой собственности, поступают в собственность того из участников, который их произвел.","article_title":"Статья 245. Определение долей в праве долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"78c944cd559405f49cfb4712372cf5f31d6fc7dc90d003210fe9ad67241a9440"},{"code_id":"GK_RF","article_number":"246","version_date":"1994-11-30","article_text":"1. Распоряжение имуществом, находящимся в долевой собственности, осуществляется по соглашению всех ее участников.\n\n2. Участник долевой собственности вправе по своему усмотрению продать, подарить, завещать, отдать в залог свою долю либо распорядиться ею иным образом с соблюдением при ее возмездном отчуждении правил, предусмотренных статьей 250 настоящего Кодекса.","article_title":"Статья 246. Распоряжение имуществом, находящимся в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e5cb8491b406a0e9ddd340c3cb15dc803cef761f587ca7808450aee172a5da04"},{"code_id":"GK_RF","article_number":"247","version_date":"1994-11-30","article_text":"1. Владение и пользование имуществом, находящимся в долевой собственности, осуществляются по соглашению всех ее участников, а при недостижении согласия - в порядке, устанавливаемом судом.\n\n2. Участник долевой собственности имеет право на предоставление в его владение и пользование части общего имущества, соразмерной его доле, а при невозможности этого вправе требовать от других участников, владеющих и пользующихся имуществом, приходящимся на его долю, соответствующей компенсации.","article_title":"Статья 247. Владение и пользование имуществом, находящимся в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5061305d604f57efe40133a162bb0dd92565bc7e2959c3e877ff4b399f0e81a8"},{"code_id":"GK_RF","article_number":"248","version_date":"1994-11-30","article_text":"Плоды, продукция и доходы от использования имущества, находящегося в долевой собственности, поступают в состав общего имущества и распределяются между участниками долевой собственности соразмерно их долям, если иное не предусмотрено соглашением между ними.","article_title":"Статья 248. Плоды, продукция и доходы от использования имущества, находящегося в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e0aba76e9c6976b4d95acb636832fddb65138acd06f1a1001d2be27faef22e1b"},{"code_id":"GK_RF","article_number":"249","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 24.07.2023 № 351-ФЗ)\n\nКаждый участник долевой собственности обязан соразмерно со своей долей участвовать в уплате налогов, сборов и иных обязательных платежей по общему имуществу, а также в расходах и издержках по его содержанию и сохранению. (В редакции  Федерального закона от 24.07.2023 № 351-ФЗ)","article_title":"Статья 249. Бремя содержания имущества, находящегося в долевой собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"62c654365e4086be6b9b90d5a1adfed423d3abd32a63db434a3e4bf30d871526"},{"code_id":"GK_RF","article_number":"25","version_date":"1994-11-30","article_text":"1. Гражданин, который не способен удовлетворить требования кредиторов по денежным обязательствам и (или) исполнить обязанность по уплате обязательных платежей, может быть признан несостоятельным (банкротом) по решению арбитражного суда.\n\n2. Основания, порядок и последствия признания арбитражным судом гражданина несостоятельным (банкротом), очередность удовлетворения требований кредиторов, порядок применения процедур в деле о несостоятельности (банкротстве) гражданина устанавливаются законом, регулирующим вопросы несостоятельности (банкротства).\n\n(Статья в редакции Федерального закона от 29.06.2015 № 154-ФЗ)","article_title":"Статья 25. Несостоятельность (банкротство) гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"111437fcd884089602b96a071cfe392be5e17cb432a8689487f1ff01ba897492"},{"code_id":"GK_RF","article_number":"250","version_date":"1994-11-30","article_text":"Публичные торги для продажи доли в праве общей собственности при отсутствии согласия на это всех участников долевой собственности могут проводиться в случаях, предусмотренных частью второй статьи 255 настоящего Кодекса, и в иных случаях, предусмотренных законом.\n\nЕсли остальные участники долевой собственности не приобретут продаваемую долю в праве собственности на недвижимое имущество в течение месяца, а в праве собственности на движимое имущество в течение десяти дней со дня извещения, продавец вправе продать свою долю любому лицу. В случае, если все остальные участники долевой собственности в письменной форме откажутся от реализации преимущественного права покупки продаваемой доли, такая доля может быть продана постороннему лицу ранее указанных сроков.\n\nОсобенности извещения участников долевой собственности о намерении продавца доли в праве общей собственности продать свою долю постороннему лицу могут быть установлены федеральным законом.\n\n(Пункт в редакции Федерального закона от 03.07.2016 № 315-ФЗ)","article_title":"Статья 250. Преимущественное право покупки","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"14f0acddb6fcf40fc9cff2f059fc7c8307a0cabfaa20711c58999ad46e160bcc"},{"code_id":"GK_RF","article_number":"251","version_date":"1994-11-30","article_text":"Доля в праве общей собственности переходит к приобретателю по договору с момента заключения договора, если соглашением сторон не предусмотрено иное.\n\nМомент перехода доли в праве общей собственности по договору, подлежащему государственной регистрации, определяется в соответствии с пунктом 2 статьи 223 настоящего Кодекса.","article_title":"Статья 251. Момент перехода доли в праве общей собственности к приобретателю по договору","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4aaf214912050a0003996b360640981797d56c571bb558a8e5d02d2bb5c60cb3"},{"code_id":"GK_RF","article_number":"252","version_date":"1994-11-30","article_text":"1. Имущество, находящееся в долевой собственности, может быть разделено между ее участниками по соглашению между ними.\n\n2. Участник долевой собственности вправе требовать выдела своей доли из общего имущества.\n\n3. При недостижении участниками долевой собственности соглашения о способе и условиях раздела общего имущества или выдела доли одного из них участник долевой собственности вправе в судебном порядке требовать выдела в натуре своей доли из общего имущества.\n\nЕсли выдел доли в натуре не допускается законом или невозможен без несоразмерного ущерба имуществу, находящемуся в общей собственности, выделяющийся собственник имеет право на выплату ему стоимости его доли другими участниками долевой собственности.\n\n4. Несоразмерность имущества, выделяемого в натуре участнику долевой собственности на основании настоящей статьи, его доле в праве собственности устраняется выплатой соответствующей денежной суммы или иной компенсацией.\n\nВыплата участнику долевой собственности остальными собственниками компенсации вместо выдела его доли в натуре допускается с его согласия. В случаях, когда доля собственника незначительна, не может быть реально выделена и он не имеет существенного интереса в использовании общего имущества, суд может и при отсутствии согласия этого собственника обязать остальных участников долевой собственности выплатить ему компенсацию.\n\n5. С получением компенсации в соответствии с настоящей статьей собственник утрачивает право на долю в общем имуществе.","article_title":"Статья 252. Раздел имущества, находящегося в долевой собственности, и выдел из него доли","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"100d76d3394c5e725acbcb56393af7435d16e5e0fc9b8a1e2da492f42a2898f1"},{"code_id":"GK_RF","article_number":"253","version_date":"1994-11-30","article_text":"1. Участники совместной собственности, если иное не предусмотрено соглашением между ними, сообща владеют и пользуются общим имуществом.\n\n2. Распоряжение имуществом, находящимся в совместной собственности, осуществляется по согласию всех участников, которое предполагается независимо от того, кем из участников совершается сделка по распоряжению имуществом.\n\n3. Каждый из участников совместной собственности вправе совершать сделки по распоряжению общим имуществом, если иное не вытекает из соглашения всех участников. Совершенная одним из участников совместной собственности сделка, связанная с распоряжением общим имуществом, может быть признана недействительной по требованию остальных участников по мотивам отсутствия у участника, совершившего сделку, необходимых полномочий только в случае, если доказано, что другая сторона в сделке знала или заведомо должна была знать об этом.\n\n4. Правила настоящей статьи применяются\n\nпостольку, поскольку для отдельных видов совместной собственности настоящим Кодексом или другими законами не установлено иное.","article_title":"Статья 253. Владение, пользование и распоряжение имуществом, находящимся в совместной собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38a022f27e1938e44519c2d653c6bb9765e5141c4ec020bba7d2a0b9d722f9a0"},{"code_id":"GK_RF","article_number":"254","version_date":"1994-11-30","article_text":"1. Раздел общего имущества между участниками совместной собственности, а также выдел доли одного из них могут быть осуществлены после предварительного определения доли каждого из участников в праве на общее имущество.\n\n2. При разделе общего имущества и выделе из него доли, если иное не предусмотрено законом или соглашением участников, их доли признаются равными.\n\n3. Основания и порядок раздела общего имущества и выдела из него доли определяются по правилам статьи 252 настоящего Кодекса постольку, поскольку иное для отдельных видов совместной собственности не установлено настоящим Кодексом, другими законами и не вытекает из существа отношений участников совместной собственности.","article_title":"Статья 254. Раздел имущества, находящегося в совместной собственности, и выдел из него доли","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bb8c39b625efb7f797a3d8d2e4c37f0b0057ef5dbc7ac311666abb990a65ca83"},{"code_id":"GK_RF","article_number":"255","version_date":"1994-11-30","article_text":"Кредитор участника долевой или совместной собственности при недостаточности у собственника другого имущества вправе предъявить требование о выделе доли должника в общем имуществе для обращения на нее взыскания.\n\nЕсли в таких случаях выделение доли в натуре невозможно либо против этого возражают остальные участники долевой или совместной собственности, кредитор вправе требовать продажи должником своей доли остальным участникам общей собственности по цене, соразмерной рыночной стоимости этой доли, с обращением вырученных от продажи средств в погашение долга.\n\nВ случае отказа остальных участников общей собственности от приобретения доли должника кредитор вправе требовать по суду обращения взыскания на долю должника в праве общей собственности путем продажи этой доли с публичных торгов.","article_title":"Статья 255. Обращение взыскания на долю в общем имуществе","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"de191f33fcd9768bdaa0dd0e75995a6a22df00ce6eead77f00d6f9891cf8c824"},{"code_id":"GK_RF","article_number":"256","version_date":"1994-11-30","article_text":"Вещи индивидуального пользования (одежда, обувь и т.п.), за исключением драгоценностей и других предметов роскоши, хотя и приобретенные во время брака за счет общих средств супругов, признаются собственностью того супруга, который ими пользовался.\n\nИмущество каждого из супругов может быть признано судом их совместной собственностью, если будет установлено, что в течение брака за счет общего имущества супругов или личного имущества другого супруга были произведены вложения, значительно увеличивающие стоимость этого имущества (капитальный ремонт, реконструкция, переоборудование и т.п.). Настоящее правило не применяется, если брачным договором между супругами предусмотрено иное. (В редакции федеральных законов от 30.12.2015 № 457-ФЗ, от 19.07.2018 № 217-ФЗ)\n\nИсключительное право на результат интеллектуальной деятельности, принадлежащее автору такого результата (статья 1228), не входит в общее имущество супругов. Однако доходы, полученные от использования такого результата, являются совместной собственностью супругов, если брачным договором между ними не предусмотрено иное. (Дополнение абзацем - Федеральный закон от 18.12.2006 № 231-ФЗ) (В редакции Федерального закона от 19.07.2018 № 217-ФЗ)\n\nВ случае смерти одного из супругов пережившему супругу принадлежит доля в праве на общее имущество супругов, равная одной второй, если иной размер доли не был определен брачным договором, совместным завещанием супругов, наследственным договором или решением суда. (Дополнение абзацем - Федеральный закон от 19.07.2018 № 217-ФЗ)","article_title":"Статья 256. Общая собственность супругов","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3f39e75e069f4658b41038fe2ceed86c3cd278daca6f66c218d24ea9f27aa5e"},{"code_id":"GK_RF","article_number":"257","version_date":"1994-11-30","article_text":"1. Имущество крестьянского (фермерского) хозяйства принадлежит его членам на праве совместной собственности, если законом или договором между ними не установлено иное.","article_title":"Статья 257. Собственность крестьянского (фермерского) хозяйства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"01b9c8826a967164cd2808d942e95153a15b13a184c7ecc964e70f8622fe8d42"},{"code_id":"GK_RF","article_number":"258","version_date":"1994-11-30","article_text":"1. При прекращении крестьянского (фермерского) хозяйства в связи с выходом из него всех его членов или по иным основаниям общее имущество подлежит разделу по правилам, предусмотренным статьями 252 и 254 настоящего Кодекса.\n\nЗемельный участок в таких случаях делится по правилам, установленным настоящим Кодексом и земельным законодательством.\n\n2. Земельный участок и средства производства, принадлежащие крестьянскому (фермерскому) хозяйству, при выходе одного из его членов из хозяйства разделу не подлежат. Вышедший из хозяйства имеет право на получение денежной компенсации, соразмерной его доле в общей собственности на это имущество.\n\n3. В случаях, предусмотренных настоящей статьей, доли членов крестьянского (фермерского) хозяйства в праве совместной собственности на имущество хозяйства признаются равными, если соглашением между ними не установлено иное.","article_title":"Статья 258. Раздел имущества крестьянского (фермерского) хозяйства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ba3658a6b87aca84551af713110856e36e5b627e7caaae0a8700259b28e4ef81"},{"code_id":"GK_RF","article_number":"259","version_date":"1994-11-30","article_text":"1. Членами крестьянского (фермерского) хозяйства на базе имущества хозяйства может быть создано хозяйственное товарищество или производственный кооператив. Такое хозяйственное товарищество или кооператив как юридическое лицо обладает правом собственности на имущество, переданное ему в форме вкладов и других взносов членами фермерского хозяйства, а также на имущество, полученное в результате его деятельности и приобретенное по иным основаниям, допускаемым законом.\n\n2. Размер вкладов участников товарищества или членов кооператива, созданного на базе имущества крестьянского (фермерского) хозяйства, устанавливается исходя из их долей в праве общей собственности на имущество хозяйства, определяемых в соответствии с пунктом 3 статьи 258 настоящего Кодекса.\n\n(Дополнение параграфом - Федеральный закон от 24.07.2023 № 351-ФЗ)","article_title":"Статья 259. Собственность хозяйственного товарищества или кооператива, образованного на базе имущества крестьянского (фермерского) хозяйства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0f36f02ac08b0a766d772c817e11b6fe15af32f0bfe2733b931f2a21b80e0c55"},{"code_id":"GK_RF","article_number":"259.1","version_date":"1994-11-30","article_text":"1. Собственникам недвижимых вещей, расположенных в пределах определенной в соответствии с законом общей территории и связанных физически или технологически либо расположенных в здании или сооружении, принадлежит на праве общей долевой собственности имущество, использование которого предполагалось для удовлетворения общих потребностей таких собственников при создании или образовании этих недвижимых вещей, а также имущество, приобретенное, созданное или образованное в дальнейшем для этой же цели (общее имущество).\n\n2. Если в порядке, установленном законом, определены границы общей территории и предусмотрено создание на ней общего имущества, то собственникам земельных участков, расположенных на этой территории, принадлежат также доли в праве общей собственности на земельные участки общего назначения, если иное не предусмотрено законом.\n\n3. Состав общего имущества может быть определен в соответствии с законом.\n\n4. Если принадлежащее собственнику здание или сооружение расположено на земельном участке, собственником которого является иное лицо, то законом может быть предусмотрено, что доля в праве общей собственности на общее имущество принадлежит такому собственнику здания или сооружения.\n\n5. Собственник недвижимой вещи вправе получать информацию о любых решениях, принятых общим собранием собственников недвижимых вещей, от лиц, на которых в силу закона или решения общего собрания собственников возложены обязанности по хранению такой информации.\n\n6. Положения параграфа 1 настоящей главы применяются к отношениям собственников недвижимых вещей по поводу принадлежащего им общего имущества, если иное не предусмотрено настоящей статьей и статьями 2592 - 2594 настоящего Кодекса.","article_title":"Статья 259.1. Право общей долевой собственности собственников недвижимых вещей на общее имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4091e8f807d5f631df656e158be7241a0bf78323c6e09ab6aaf5a62b35e32f28"},{"code_id":"GK_RF","article_number":"259.2","version_date":"1994-11-30","article_text":"1. Доля в праве общей собственности на общее имущество, принадлежащая собственнику одной недвижимой вещи, пропорциональна площади принадлежащей ему соответствующей недвижимой вещи, если иное не установлено законом.\n\n2. Доля в праве общей собственности на общее имущество следует судьбе права собственности на недвижимую вещь, не может быть выделена в натуре и не может быть отчуждена отдельно от права собственности на недвижимую вещь. Собственник недвижимой вещи не вправе также совершать иные действия, влекущие передачу такой доли отдельно от права собственности на недвижимую вещь. Сделки, совершенные с нарушением положений настоящего пункта, ничтожны.","article_title":"Статья 259.2. Доля в праве общей собственности на общее имущество","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"404f29a0404754ac42ce0a40ba57a5a21873eb05e9c0c420863ad251831e87d9"},{"code_id":"GK_RF","article_number":"259.3","version_date":"1994-11-30","article_text":"1. Каждый собственник недвижимой вещи вправе владеть и пользоваться общим имуществом наряду с собственниками иных недвижимых вещей, если иной порядок не определен решением собственников недвижимых вещей, настоящим Кодексом или законом.\n\n2. За исключением случаев, предусмотренных пунктами 4 и 5 настоящей статьи, решение собственников недвижимых вещей по вопросам владения, пользования и распоряжения общим имуществом принимается большинством голосов всех собственников недвижимых вещей, если иное число голосов не предусмотрено настоящим Кодексом или законом.\n\n3. Количество голосов, принадлежащих собственнику недвижимой вещи, пропорционально размеру принадлежащей ему доли в праве собственности на общее имущество.\n\n4. Пригодное для самостоятельного использования общее имущество может быть передано во владение или пользование третьим лицам, если такая передача не повлечет нарушение прав и охраняемых законом интересов собственников недвижимых вещей. Передача общего имущества во владение или пользование третьим лицам осуществляется на основании решения собственников недвижимых вещей, принятого не менее чем двумя третями голосов собственников недвижимых вещей.\n\n5. Недвижимые вещи, относящиеся к общему имуществу, не подлежат передаче в собственность третьим лицам, за исключением случаев, если решение об этой передаче принято собственниками недвижимых вещей единогласно при условии, что эта передача не противоречит закону.","article_title":"Статья 259.3. Владение, пользование и распоряжение общим имуществом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bec0f7f4e23bc0c64389570f7d4fea2a04e62504fa87314c62a64f749b460d6"},{"code_id":"GK_RF","article_number":"259.4","version_date":"1994-11-30","article_text":"1. Если иное не установлено единогласным решением собственников недвижимых вещей, каждый собственник недвижимой вещи обязан участвовать в расходах и издержках по содержанию и сохранению общего имущества соразмерно со своей долей в праве на общее имущество (пункт 1 статьи 2592). Собственник недвижимой вещи, в результате действий или бездействия которого возникают дополнительные расходы и издержки по содержанию и сохранению общего имущества, обязан их покрывать.\n\n2. Каждый собственник недвижимой вещи обязан соразмерно со своей долей в праве общей собственности на общее имущество (пункт 1 статьи 2592) участвовать в уплате налогов, сборов и иных обязательных платежей, связанных с общим имуществом.\n\n(Наименование в редакции Федерального закона от 16.04.2001 № 45-ФЗ)\n\n____________________________\n\n* (Сноска исключена - Федеральный закон от 16.04.2001 № 45-ФЗ)","article_title":"Статья 259.4. Бремя содержания общего имущества","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38f94279b2ebbe509be61458a744aa9a3ec5663367f0f058cc7342d50a4a8563"},{"code_id":"GK_RF","article_number":"26","version_date":"1994-11-30","article_text":"1. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет совершают сделки, за исключением названных в пункте 2 настоящей статьи, с письменного согласия своих законных представителей - родителей, усыновителей или попечителя.\n\nСделка, совершенная таким несовершеннолетним, действительна также при ее последующем письменном одобрении его родителями, усыновителями или попечителем.\n\n2. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет вправе самостоятельно, без согласия родителей, усыновителей и попечителя:\n\n1) распоряжаться своими заработком, стипендией и иными доходами;\n\n2) осуществлять права автора произведения науки, литературы или искусства, изобретения или иного охраняемого законом результата своей интеллектуальной деятельности;\n\n3) в соответствии с законом вносить вклады в кредитные организации и распоряжаться ими; (В редакции Федерального закона от 30.12.2012 № 302-ФЗ)\n\n4) совершать мелкие бытовые сделки и иные сделки, предусмотренные пунктом 2 статьи 28 настоящего Кодекса.\n\nПо достижении шестнадцати лет несовершеннолетние также вправе быть членами кооперативов в соответствии с законами о кооперативах.\n\n3. Несовершеннолетние в возрасте от четырнадцати до восемнадцати лет самостоятельно несут имущественную ответственность по сделкам, совершенным ими в соответствии с пунктами 1 и 2 настоящей статьи. За причиненный ими вред такие несовершеннолетние несут ответственность в соответствии с настоящим Кодексом.\n\n4. При наличии достаточных оснований суд по ходатайству родителей, усыновителей или попечителя либо органа опеки и попечительства может ограничить или лишить несовершеннолетнего в возрасте от четырнадцати до восемнадцати лет права самостоятельно распоряжаться своими заработком, стипендией или иными доходами, за исключением случаев, когда такой несовершеннолетний приобрел дееспособность в полном объеме в соответствии с пунктом 2 статьи 21 или со статьей 27 настоящего Кодекса.","article_title":"Статья 26. Дееспособность несовершеннолетних в возрасте от четырнадцати до восемнадцати лет","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c7ba5a4e9bb5a9d37ba43cb75f8d1f18e07d97a94e116c344b570cd32d3985ca"},{"code_id":"GK_RF","article_number":"260","version_date":"1994-11-30","article_text":"1. Лица, имеющие в собственности земельный участок, вправе продавать его, дарить, отдавать в залог или сдавать в аренду и распоряжаться им иным образом (статья 209) постольку, поскольку соответствующие земли на основании закона не исключены из оборота или не ограничены в обороте.","article_title":"Статья 260. Общие положения о праве собственности на землю","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d7325c7dcccc17ac76253f8c8fb14c888d0c075766454cfce8b2bca21c58cea"},{"code_id":"GK_RF","article_number":"262","version_date":"1994-11-30","article_text":"1. Граждане имеют право свободно, без каких-либо разрешений находиться на не закрытых для общего доступа земельных участках, находящихся в государственной или муниципальной собственности, и использовать имеющиеся на этих участках природные объекты в пределах, допускаемых законом и иными правовыми актами, а также собственником соответствующего земельного участка.\n\n2. Если земельный участок не огорожен либо его собственник иным способом ясно не обозначил, что вход на участок без его разрешения не допускается, любое лицо может пройти через участок при условии, что это не причиняет ущерба или беспокойства собственнику.","article_title":"Статья 262. Земельные участки общего пользования. Доступ на земельный участок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d99e902b5c5fcaf95ec84312ce01043b2af553ca2e902a0af109b30efba01905"},{"code_id":"GK_RF","article_number":"263","version_date":"1994-11-30","article_text":"Последствия самовольной постройки, возведенной или созданной на земельном участке его собственником или другими лицами, определяются статьей 222 настоящего Кодекса. (В редакции Федерального закона от 03.08.2018 № 339-ФЗ)","article_title":"Статья 263. Застройка земельного участка","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eefb2d2fd46c5048acf41528efa5b8b3bbfca067f67917d3ac3a72c0eb0411f2"},{"code_id":"GK_RF","article_number":"265","version_date":"1994-11-30","article_text":"Право пожизненного наследуемого владения земельным участком, находящимся в государственной или муниципальной собственности, приобретается гражданами по основаниям и в порядке, которые предусмотрены земельным законодательством.","article_title":"Статья 265. Основания приобретения права пожизненного наследуемого владения земельным участком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"28f23bb57edc32982329e39835b80b639e160688f5cd613844af53c8ef5ca754"},{"code_id":"GK_RF","article_number":"266","version_date":"1994-11-30","article_text":"1. Гражданин, обладающий правом пожизненного наследуемого владения (владелец земельного участка), имеет права владения и пользования земельным участком, передаваемые по наследству.\n\n2. Если из условий пользования земельным участком, установленных законом, не вытекает иное, владелец земельного участка вправе возводить на нем здания, сооружения и создавать другое недвижимое имущество, приобретая на него право собственности.","article_title":"Статья 266. Владение и пользование земельным участком на праве пожизненного наследуемого владения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a76d26713b5b80d12f40433eb3ca68294a3ad3926484d6f65d4e8b6620d137f8"},{"code_id":"GK_RF","article_number":"267","version_date":"1994-11-30","article_text":"Распоряжение земельным участком, находящимся в пожизненном наследуемом владении, не допускается, за исключением случая перехода права на земельный участок по наследству.\n\n(Статья в редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 267. Распоряжение земельным участком, находящимся в пожизненном наследуемом владении","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e6f4abafe92aa2cb78e76a7bfc2dc48cb88122acf2c9637bc5450567d34d2eb7"},{"code_id":"GK_RF","article_number":"269","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 26.06.2007 № 118-ФЗ)","article_title":"Статья 269. Владение и пользование землей на праве постоянного (бессрочного) пользования","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"870c2b91ffceaf0f97e66ccaca7dbb0e5e7d516f363d8baef1cfec2d84300b08"},{"code_id":"GK_RF","article_number":"27","version_date":"1994-11-30","article_text":"1. Несовершеннолетний, достигший шестнадцати лет, может быть объявлен полностью дееспособным, если он работает по трудовому договору, в том числе по контракту, или с согласия родителей, усыновителей или попечителя занимается предпринимательской деятельностью.\n\nОбъявление несовершеннолетнего полностью дееспособным (эмансипация) производится по решению органа опеки и попечительства - с согласия обоих родителей, усыновителей или попечителя либо при отсутствии такого согласия - по решению суда.\n\n2. Родители, усыновители и попечитель не несут ответственности по обязательствам эмансипированного несовершеннолетнего, в частности по обязательствам, возникшим вследствие причинения им вреда.","article_title":"Статья 27. Эмансипация","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"95bf174b23ac123f5c33f610c271322b9ece52af332ef669705aed0d34aa8834"},{"code_id":"GK_RF","article_number":"270","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 04.12.2006 № 201-ФЗ)","article_title":"Статья 270. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6c6f22bda7927df672a8606db25b368d0206f4396dd6b8b2ca0524b80c07670c"},{"code_id":"GK_RF","article_number":"271","version_date":"1994-11-30","article_text":"1. Собственник здания, сооружени\n\nя или иной недвижимости, находящейся на земельном участке, принадлежащем другому лицу, имеет право пользования предоставленным таким лицом под эту недвижимость земельным участком. (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 26.06.2007 № 118-ФЗ)\n\nПереход права собственности на земельный участок не является основанием прекращения или изменения принадлежащего собственнику недвижимости права пользования этим участком.","article_title":"Статья 271. Право пользования земельным участком собственником недвижимости","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c612423eab26be0fa8455d901a82dacfe5953f3ffca40f9050316c667127b688"},{"code_id":"GK_RF","article_number":"272","version_date":"1994-11-30","article_text":"1. При прекращении права пользования земельным участком, предоставленного собственнику находящегося на этом участке недвижимого имущества (статья 271), права на недвижимость, оставленную ее собственником на земельном участке, определяются в соответствии с соглашением между собственником участка и собственником соответствующего недвижимого имущества.\n\n2. При отсутствии или недостижении соглашения, указанного в пункте 1 настоящей статьи, последствия прекращения права пользования земельным участком определяются судом по требованию собственника земельного участка или собственника недвижимости.\n\nСобственник земельного участка вправе требовать по суду, чтобы собственник недвижимости после прекращения права пользования участком освободил его от недвижимости и привел участок в первоначальное состояние.\n\nВ случаях, когда снос здания или сооружения, находящегося на земельном участке, запрещен в соответствии с законом и иными правовыми актами (жилые дома, памятники истории и культуры и т.п.) либо не подлежит осуществлению ввиду явного превышения стоимости здания или сооружения по сравнению со стоимостью отведенной под него земли, суд с учетом оснований прекращения права пользования земельным участком и при предъявлении соответствующих требований сторонами может:\n\nпризнать право собственника недвижимости на приобретение в собственность земельного участка, на котором находится эта недвижимость, или право собственника земельного участка на приобретение оставшейся на нем недвижимости, либо\n\nустановить условия пользования земельным участком собственником недвижимости на новый срок.","article_title":"Статья 272. Последствия утраты собственником недвижимости права пользования земельным участком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2dab1057b59acfc2d9cc1614307937cdf5c0973f87e54e6fadd41e72998dc43d"},{"code_id":"GK_RF","article_number":"273","version_date":"1994-11-30","article_text":"При переходе права собственности на здание или сооружение, принадлежавшее собственнику земельного участка, на котором оно находится, к приобретателю здания или сооружения переходит право собственности на земельный участок, занятый зданием или сооружением и необходимый для его использования, если иное не предусмотрено законом.  (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)\n\nЧасть. (Утратила силу - Федеральный закон от 26.06.2007 № 118-ФЗ)","article_title":"Статья 273. Переход права на земельный участок при отчуждении находящихся на нем зданий или сооружений","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4c9fe0ab47039e50e4714052279f6ae3717f90a8647b0119440f15d1cc7fab35"},{"code_id":"GK_RF","article_number":"274","version_date":"1994-11-30","article_text":"1. Собственник недвижимого имущества (земельного участка, другой недвижимости) вправе требовать от собственника соседнего земельного участка, а в необходимых случаях и от собственника другого земельного участка (соседнего участка) предоставления права ограниченного пользования соседним участком (сервитута).\n\nСервитут может устанавливаться для обеспечения прохода и проезда через соседний земельный участок, строительства, реконструкции и (или) эксплуатации линейных объектов, не препятствующих использованию земельного участка в соответствии с разрешенным использованием, а также других нужд собственника недвижимого имущества, которые не могут быть обеспечены без установления сервитута. (В редакции Федерального закона от 23.06.2014 № 171-ФЗ)\n\n2. Обременение земельного участка сервитутом не лишает собственника участка прав владения, пользования и распоряжения этим участком.\n\n3. Сервитут устанавливается по соглашению между лицом, требующим установления сервитута, и собственником соседнего участка и подлежит регистрации в порядке, установленном для регистрации прав на недвижимое имущество. В случае недостижения соглашения об установлении или условиях сервитута спор разрешается судом по иску лица, требующего установления сервитута.","article_title":"Статья 274. Право ограниченного пользования чужим земельным участком (сервитут)","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df21212e064f4eddc2113c554e38c0c687625f7a9345fc0963d7dd69488d7cc1"},{"code_id":"GK_RF","article_number":"276","version_date":"1994-11-30","article_text":"1. По требованию собственника земельного участка, обремененного сервитутом, сервитут может быть прекращен ввиду отпадения оснований, по которым он был установлен.","article_title":"Статья 276. Прекращение сервитута","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b97abbc8aed98206f8e9561fd901442c61f8832e0e900a3bd606ff9c4bad90c7"},{"code_id":"GK_RF","article_number":"277","version_date":"1994-11-30","article_text":"Применительно к правилам, предусмотренным статьями 274 - 276 настоящего Кодекса, сервитутом могут обременяться здания, сооружения и другое недвижимое имущество, ограниченное пользование которым необходимо вне связи с пользованием земельным участком.","article_title":"Статья 277. Обременение сервитутом зданий и сооружений","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9731f4d3a522167fc84d569be8223c4657c8e27c66073c2e0075dd432a453b1b"},{"code_id":"GK_RF","article_number":"278","version_date":"1994-11-30","article_text":"Обращение взыскания на земельный участок по обязательствам его собственника допускается только на основании решения суда.","article_title":"Статья 278. Обращение взыскания на земельный участок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f54853a81e304434bd6d029e04c54724d39d9070472866fe093a1feefd042fa0"},{"code_id":"GK_RF","article_number":"279","version_date":"1994-11-30","article_text":"1. Изъятие земельного участка для государственных или муниципальных нужд осуществляется в случаях и в порядке, которые предусмотрены земельным законодательством.\n\n2. В результате изъятия земельного участка для государственных или муниципальных нужд осуществляется:\n\n1) прекращение права собственности гражданина или юридического лица на такой земельный участок;\n\n2) прекращение права постоянного (бессрочного) пользования, пожизненного наследуемого владения земельным участком, находящимся в государственной или муниципальной собственности;\n\n3) досрочное прекращение договора аренды земельного участка, находящегося в государственной или муниципальной собственности, или договора безвозмездного пользования таким земельным участком.\n\n3. Решение об изъятии земельного участка для государственных или муниципальных нужд принимается федеральными органами исполнительной власти, органами исполнительной власти субъектов Российской Федерации или органами местного самоуправления, определяемыми в соответствии с земельным законодательством.\n\n4. Со дня прекращения прав на изъятый земельный участок прежнего правообладателя прекращаются сервитут, залог, установленные в отношении такого земельного участка, а также договоры, заключенные данным правообладателем в отношении такого земельного участка. Сервитуты, установленные в отношении изъятого земельного участка, сохраняются в случае, если использование такого земельного участка на условиях сервитута не противоречит целям, для которых осуществляется изъятие земельного участка.\n\nВ случае, если изъятие земельного участка для государственных или муниципальных нужд делает невозможным исполнение правообладателем земельного участка иных обязательств перед третьими лицами, в том числе обязательств, основанных на заключенных правообладателем земельного участка с такими лицами договорах, решение об изъятии земельного участка для государственных или муниципальных нужд является основанием для прекращения этих обязательств.\n\n5. Правообладатель земельного участка должен быть уведомлен о принятом решении об изъятии земельного участка для государственных или муниципальных нужд в соответствии с земельным законодательством.\n\n6. Сроки, размер возмещения и другие условия, на которых осуществляется изъятие земельного участка для государственных или муниципальных нужд, определяются соглашением об изъятии земельного участка и расположенных на нем объектов недвижимости для государственных или муниципальных нужд (далее - соглашение об изъятии). В случае принудительного изъятия такие условия определяются судом.\n\n(Статья в редакции Федерального закона от 31.12.2014 № 499-ФЗ)","article_title":"Статья 279. Изъятие земельного участка для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"710ecec0b8d5a6864456db476411393a7fe9a2ca73ec39eabc113756b1ce0c0e"},{"code_id":"GK_RF","article_number":"28","version_date":"1994-11-30","article_text":"1. За несовершеннолетних, не достигших четырнадцати лет (малолетних), сделки, за исключением указанных в пункте 2 настоящей статьи, могут совершать от их имени только их родители, усыновители или опекуны.\n\nК сделкам законных представителей несовершеннолетнего с его имуществом применяются правила, предусмотренные пунктами 2 и 3 статьи 37 настоящего Кодекса.\n\n2. Малолетние в возрасте от шести до четырнадцати лет вправе самостоятельно совершать:\n\n1) мелкие бытовые сделки;\n\n2) сделки, направленные на безвозмездное получение выгоды, не требующие нотариального удостоверения либо государственной регистрации;\n\n3) сделки по распоряжению средствами, предоставленными законным представителем или с согласия последнего третьим лицом для определенной цели или для свободного распоряжения.\n\n3. Имущественную ответственность по сделкам малолетнего, в том числе по сделкам, совершенным им самостоятельно, несут его родители, усыновители или опекуны, если не докажут, что обязательство было нарушено не по их вине. Эти лица в соответствии с законом также отвечают за вред, причиненный малолетними.","article_title":"Статья 28. Дееспособность малолетних","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b0c8639fbce1be7ead70ccf8cc0e65e8a6e156057032b94e7433ae7e46b09251"},{"code_id":"GK_RF","article_number":"280","version_date":"1994-11-30","article_text":"Лица, права которых на земельный участок прекращаются в силу его изъятия для государственных или муниципальных нужд, до дня прекращения данных прав владеют, пользуются и распоряжаются в соответствии с законом таким земельным участком по своему усмотрению. При этом лица, указанные в настоящей статье, несут риск отнесения на них затрат и убытков, связанных со строительством, с реконструкцией зданий, сооружений, осуществлением неотделимых улучшений, со дня уведомления их о принятом решении об изъятии земельного участка для государственных или муниципальных нужд в соответствии с земельным законодательством.\n\n(Статья в редакции Федерального закона от 31.12.2014 № 499-ФЗ)","article_title":"Статья 280. Пользование и распоряжение земельным участком, подлежащим изъятию для государственных или муниципальных нужд","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"452c467c044c8f1c2fc34e2bd6676075ee41e285143f06f5945a257db7576e06"},{"code_id":"GK_RF","article_number":"281","version_date":"1994-11-30","article_text":"1. За земельный участок, изымаемый для государственных или муниципальных нужд, его правообладателю предоставляется возмещение.\n\n2. При определении размера возмещения при изъятии земельного участка для государственных или муниципальных нужд в него включаются рыночная стоимость земельного участка, право собственности на который подлежит прекращению, или рыночная стоимость иных прав на земельный участок, подлежащих прекращению, и убытки, причиненные изъятием такого земельного участка, в том числе упущенная выгода, и определяемые в соответствии с федеральным законодательством.\n\nВ случае, если одновременно с изъятием земельного участка для государственных или муниципальных нужд осуществляется изъятие расположенных на таком земельном участке и принадлежащих правообладателю данного земельного участка объектов недвижимого имущества, в возмещение за изымаемое имущество включается рыночная стоимость объектов недвижимого имущества, право собственности на которые подлежит прекращению, или рыночная стоимость иных прав на объекты недвижимого имущества, подлежащих прекращению.\n\n3. При наличии согласия лица, у которого изымается земельный участок, в соглашении об изъятии может быть предусмотрено предоставление этому лицу иного земельного участка и (или) иного недвижимого имущества на условиях и в порядке, которые определены законодательством, с зачетом стоимости такого земельного участка и (или) иного недвижимого имущества или прав на них в размер возмещения за изымаемый земельный участок.\n\n4. Принудительное изъятие земельного участка для государственных или муниципальных нужд допускается при условии предварительного и равноценного возмещения.\n\n(Статья в редакции Федерального закона от 31.12.2014 № 499-ФЗ)","article_title":"Статья 281. Возмещение за изымаемый земельный участок","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"37b80cee316b3a0fac8f7bdb513bd36a51846af7d3a6ab9096d9074653887fdc"},{"code_id":"GK_RF","article_number":"282","version_date":"1994-11-30","article_text":"1. Если правообладатель изымаемого земельного участка не заключил соглашение об изъятии, в том числе по причине несогласия с решением об изъятии у него земельного участка, допускается принудительное изъятие земельного участка для государственных или муниципальных нужд.\n\n2. Принудительное изъятие земельного участка для государственных или муниципальных нужд осуществляется по решению суда. Иск о принудительном изъятии земельного участка для государственных или муниципальных нужд может быть предъявлен в суд в течение срока действия решения об изъятии земельного участка для государственных или муниципальных нужд. При этом указанный иск не может быть подан ранее чем до истечения девяноста дней со дня получения правообладателем такого земельного участка проекта соглашения об изъятии.\n\n(Статья в редакции Федерального закона от 31.12.2014 № 499-ФЗ)","article_title":"Статья 282. Изъятие земельного участка для государственных или муниципальных нужд по решению суда","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4eb6dd0da54b5c3d5a830123e169436356c2785469605e37fc9b3bcf470218b8"},{"code_id":"GK_RF","article_number":"283","version_date":"1994-11-30","article_text":"(Статья утратила силу - Федеральный закон от 31.12.2014 № 499-ФЗ)","article_title":"Статья 283. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"83fec0950bf4b4c96e77583783122a231270f9a2ed5905f784acec97dc5a7d2f"},{"code_id":"GK_RF","article_number":"284","version_date":"1994-11-30","article_text":"Земельный участок может быть изъят у собственника в случаях, когда участок предназначен для ведения сельского хозяйства либо жилищного или иного строительства и не используется по целевому назначению в течение трех лет, если более длительный срок не установлен законом. В этот период не включается время, необходимое для освоения участка, за исключением случаев, когда земельный участок относится к землям сельскохозяйственного назначения, оборот которых регулируется Федеральным законом от 24 июля 2002 года № 101-ФЗ \"Об обороте земель сельскохозяйственного назначения\", а также время, в течение которого участок не мог быть использован по целевому назначению из-за стихийных бедствий или ввиду иных обстоятельств, исключающих такое использование.\n\n(Статья в редакции Федерального закона от 03.07.2016 № 354-ФЗ)","article_title":"Статья 284. Изъятие земельного участка, который не используется по целевому назначению","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"040e744374855d70a6afcbfb10b01993997955df1761f235752dc3fd1bd50605"},{"code_id":"GK_RF","article_number":"285","version_date":"1994-11-30","article_text":"Земельный участок может быть изъят у собственника, если использование участка осуществляется с нарушением требований законодательства Российской Федерации, в частности, если участок используется не по целевому назначению, или его использование приводит к существенному снижению плодородия земель сельскохозяйственного назначения либо причинению вреда окружающей среде, или на участке возведена или создана самовольная постройка и лицами, указанными в пункте 2 статьи 222 настоящего Кодекса, не выполнены предусмотренные законом обязанности по ее сносу или приведению в соответствие с установленными требованиями.\n\n(Статья в редакции Федерального закона от 03.08.2018 № 339-ФЗ)","article_title":"Статья 285. Изъятие земельного участка, используемого с нарушением законодательства Российской Федерации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b88ec91895c6f4f50b378c6f4d2792536a59504c12a5b8c2be6756426b98f047"},{"code_id":"GK_RF","article_number":"286","version_date":"1994-11-30","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 354-ФЗ)\n\n1. Орган государственной власти или местного самоуправления, уполномоченный принимать решения об изъятии земельных участков по основаниям, предусмотренным статьями 284 и 285 настоящего Кодекса, а также порядок обязательного заблаговременного предупреждения собственников участков о допущенных нарушениях определяются земельным законодательством.\n\n2. Если собственник земельного участка письменно уведомит орган, принявший решение об изъятии земельного участка, о своем согласии исполнить это решение, участок подлежит продаже с публичных торгов.\n\n3. Если собственник земельного участка не согласен с решением об изъятии у него участка, орган, принявший решение об изъятии участка, может предъявить требование о продаже участка в суд.","article_title":"Статья 286. Порядок изъятия земельного участка, не используемого по целевому назначению или используемого с нарушением законодательства Российской Федерации","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ca67f8ffdb44e981a9476ba97046d2234f91f33808f117b7600991dd1e56ad1d"},{"code_id":"GK_RF","article_number":"287","version_date":"1994-11-30","article_text":"Прекращение прав на земельный участок, принадлежащих арендаторам и другим лицам, не являющимся его собственниками, ввиду ненадлежащего использования участка этими лицами осуществляется по основаниям и в порядке, которые установлены земельным законодательством.\n\n(Дополнение главой - Федеральный закон от 21.12.2021 № 430-ФЗ)","article_title":"Статья 287. Прекращение прав на земельный участок, принадлежащих лицам, не являющимся его собственниками","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1aebe804b4ec471d816ad880d7422265aefdbea43dfaac2b396dbc83074e92d5"},{"code_id":"GK_RF","article_number":"287.1","version_date":"1994-11-30","article_text":"Право собственности на созданные здание, сооружение, объект незавершенного строительства, помещение, машино-место возникает у собственника земельного участка, на котором расположены указанные объекты, если настоящим Кодексом, другим законом или договором не предусмотрено иное. Право собственности на созданные здание, сооружение, объект незавершенного строительства, помещение, машино-место возникает у лица, которому находящийся в государственной или муниципальной собственности земельный участок предоставлен для создания соответствующей недвижимой вещи, если настоящим Кодексом, другим законом или договором не предусмотрено иное.","article_title":"Статья 287.1. Возникновение права собственности на здание, сооружение, объект незавершенного строительства, помещение, машино-место при их создании","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0c0b7681b322e1eebc3b259784dcd85cb942015aa27497f7f2ef7185173b5463"},{"code_id":"GK_RF","article_number":"287.2","version_date":"1994-11-30","article_text":"1. При государственной регистрации прав на образованные в здании или сооружении помещения и (или) машино-места право собственности на здание, сооружение в целом прекращается.\n\n2. Собственник здания или сооружения вправе передать другому лицу во временное владение и пользование или во временное пользование помещение (часть помещения) либо иные части здания или сооружения. В этом случае договором между собственником и другим лицом определяется часть здания или сооружения, подлежащая передаче во временное владение и пользование или во временное пользование.\n\n3. Помещения, машино-места могут быть образованы при разделе здания, сооружения, принадлежащих нескольким лицам на праве общей долевой собственности (статья 252), в счет долей всех сособственников таких здания, сооружения в праве собственности на такие здание, сооружение.","article_title":"Статья 287.2. Особенности права собственности на здание, сооружение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f6228c9458bbb89043cd9bd3d65da8f16fb9f46348f62dfc7998467a6b873326"},{"code_id":"GK_RF","article_number":"287.3","version_date":"1994-11-30","article_text":"1. Собственник здания или сооружения, находящихся на земельном участке, принадлежащем другому лицу, пользуется данным земельным участком на условиях и в объеме, которые предусмотрены законом или договором с собственником данного земельного участка.\n\n2. Собственник здания или сооружения, находящихся на земельном участке, принадлежащем другому лицу, не имеющий права пользования этим земельным участком по закону или по договору с собственником земельного участка, вправе пользоваться данным земельным участком в объеме, необходимом для обеспечения ему доступа к таким зданию или сооружению (статья 271).\n\n3. Собственник здания или сооружения, находящихся на чужом земельном участке, имеет право владеть, пользоваться и распоряжаться этими зданием или сооружением по своему усмотрению, в том числе сносить принадлежащие ему здание или сооружение, постольку, поскольку это не противоречит условиям пользования данным земельным участком, установленным законом или договором, и не нарушает прав собственника данного земельного участка или его иного законного владельца.\n\n4. Случайная гибель здания или сооружения, находящихся на чужом земельном участке, не влечет прекращения указанного в пунктах 1 и 2 настоящей статьи права собственника этих здания или сооружения на земельный участок, если иное не предусмотрено законом или договором. Собственник погибших здания или сооружения имеет право на их восстановление в определяемом законом порядке.\n\nЕсли собственник погибших здания или сооружения, находящихся на чужом земельном участке, не приступил к восстановлению здания или сооружения в течение пяти лет с момента их случайной гибели, его право, указанное в пунктах 1 и 2 настоящей статьи, прекращается, если иное не предусмотрено законом или договором.\n\n5. Собственник здания или сооружения на земельном участке, находящемся в государственной или муниципальной собственности, вправе требовать передачи ему в собственность или во временное владение и пользование или только во временное пользование земельного участка, необходимого для их использования, в случаях и в порядке, которые предусмотрены законом.","article_title":"Статья 287.3. Пользование собственником здания или сооружения чужим земельным участком","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f25d7724d629c1b9602aeddee2855b11044510f852041e59521e8f1bf99c241"},{"code_id":"GK_RF","article_number":"287.4","version_date":"1994-11-30","article_text":"1. Собственник помещения, машино-места владеет, пользуется и распоряжается принадлежащими ему помещением, машино-местом в соответствии с их назначением. Собственник помещения, машино-места не вправе использовать их способами, которые нарушают права и охраняемые законом интересы собственников иных помещений, машино-мест, находящихся в тех же здании, сооружении.\n\n2. Собственнику помещения, машино-места принадлежит доля в праве собственности на общее имущество в таких здании или сооружении (статья 2875).\n\n3. Пользование жилым помещением для целей, не связанных с проживанием граждан, допускается только после перевода жилого помещения в порядке, определяемом жилищным законодательством, в нежилое помещение, за исключением случаев, установленных Жилищным кодексом Российской Федерации.\n\n4. В случае сноса либо разрушения здания или сооружения, в которых расположены помещения, машино-места, за собственниками таких помещений, машино-мест сохраняется право общей долевой собственности на земельный участок, на котором были расположены эти здание или сооружение.","article_title":"Статья 287.4. Особенности права собственности на помещение, машино-место","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"235d004e40a96b3c7fbf50e3d4ca894276819b35b94de719c4a3ff30b17cbae8"},{"code_id":"GK_RF","article_number":"287.6","version_date":"1994-11-30","article_text":"1. Собственники помещений, машино-мест в здании или сооружении пользуются земельным участком, на котором расположены эти здание или сооружение, в соответствии с правилами, установленными статьей 2873 настоящего Кодекса.\n\n2. Собственникам помещений в многоквартирном доме принадлежат на праве общей долевой собственности земельный участок, на котором расположен данный дом, с элементами озеленения и благоустройства, иные предназначенные для обслуживания, эксплуатации и благоустройства данного дома и расположенные на указанном земельном участке объекты.\n\n3. В случаях, предусмотренных Земельным кодексом Российской Федерации, собственники нежилых помещений в зданиях или сооружениях, расположенных на земельном участке, находящемся в государственной или муниципальной собственности, за исключением собственников нежилых помещений в многоквартирных домах, вправе требовать передачи им земельного участка, занятого зданием или сооружением и необходимого для их использования, в том числе для обеспечения их безопасной эксплуатации, в общую собственность или во временное владение и пользование или только во временное пользование.","article_title":"Статья 287.6. Права собственников помещений, машино-мест на земельный участок под зданием или сооружением","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"102bd6a9f8a2a1fd6ef7fbdc08ff33cc70c150105667b8bf7ea96d20730ff1bd"},{"code_id":"GK_RF","article_number":"287.7","version_date":"1994-11-30","article_text":"1. Если собственник помещения использует его не по назначению, систематически нарушает права и интересы соседей либо бесхозяйственно содержит помещение, допуская его разрушение, уполномоченный государственный орган или орган местного самоуправления может предупредить собственника о необходимости устранить нарушения, а если они влекут разрушение помещения, также назначить собственнику соразмерный срок для ремонта помещения.\n\nЕсли собственник помещения после предупреждения продолжит нарушать права и интересы соседей или использовать помещение не по назначению либо без уважительных причин не произведет необходимый ремонт, суд по иску уполномоченного государственного органа или органа местного самоуправления может принять решение о продаже с публичных торгов такого помещения с выплатой собственнику вырученных от продажи средств за вычетом расходов на исполнение судебного решения.\n\n2. Правила, предусмотренные настоящей статьей, применяются к отношениям, связанным с прекращением права собственности на бесхозяйственно содержимые жилые помещения, с особенностями, предусмотренными Жилищным кодексом Российской Федерации.\n\n3. Правила, предусмотренные настоящей статьей, применяются к машино-местам, если иное не предусмотрено законом и не вытекает из существа правоотношений.","article_title":"Статья 287.7. Прекращение права собственности на бесхозяйственно содержимое помещение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0fb7df793ba3bf5a6a46c05424c107576bd53ea7eb03734947871deb0ccb6e81"},{"code_id":"GK_RF","article_number":"288","version_date":"1994-11-30","article_text":"1. Собственник осуществляет права владения, пользования и распоряжения принадлежащим ему жилым помещением в соответствии с его назначением.\n\n2. Жилые помещения предназначены для проживания граждан.\n\nГражданин - собственник жилого помещения может использовать его для личного проживания и проживания членов его семьи.\n\nЖилые помещения могут сдаваться их собственниками для проживания на основании договора.\n\n3. Размещение в жилых домах промышленных производств не допускается.\n\nРазмещение собственником в принадлежащем ему жилом помещении предприятий, учреждений, организаций допускается только после перевода такого помещения в нежилое. Перевод помещений из жилых в нежилые производится в порядке, определяемом жилищным законодательством.","article_title":"Статья 288. Собственность на жилое помещение","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4bfffd19d4fd7a23d7f067cf5b5d669257971200d07509650d7025ebfb0e8be5"},{"code_id":"GK_RF","article_number":"289","version_date":"1994-11-30","article_text":"Собственнику квартиры в многоквартирном доме наряду с принадлежащим ему помещением, занимаемым под квартиру, принадлежит также доля в праве собственности на общее имущество дома (статья 290).","article_title":"Статья 289. Квартира как объект права собственности","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"948d6e6d2b835df27607e1d3100bf32c38aaadaca213edf80c5613db43c7b8ec"},{"code_id":"GK_RF","article_number":"29","version_date":"1994-11-30","article_text":"1. Гражданин,\n\nкоторый вследствие психического расстройства не может понимать значения своих действий или руководить ими, может быть признан судом недееспособным в порядке, установленном гражданским процессуальным законодательством. Над ним устанавливается опека.\n\nПри восстановлении способности гражданина, который был признан недееспособным, понимать значение своих действий или руководить ими суд признает его дееспособным.\n\nНа основании решения суда отменяется установленная над гражданином опека и в случае признания гражданина ограниченно дееспособным устанавливается попечительство.\n\n(Пункт в редакции Федерального закона от 30.12.2012 № 302-ФЗ)","article_title":"Статья 29. Признание гражданина недееспособным","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fbcf811af2bc867a95fc211d349085889b865453774195ef0486b48a6b8d5eaf"},{"code_id":"GK_RF","article_number":"290","version_date":"1994-11-30","article_text":"1. Собственникам помещений, машино-мест в многоквартирном доме принадлежат на праве общей долевой собственности общие помещения многоквартирного дома, несущие и ненесущие конструкции, механическое, электрическое, санитарно-техническое и иное оборудование многоквартирного дома, расположенное за пределами или внутри помещений, обслуживающее более одного помещения, машино-места в многоквартирном доме, а также земельный участок, указанный в пункте 2 статьи 2876 настоящего Кодекса.\n\n2. Собственник помещения, машино-места не вправе отчуждать свою долю в праве собственности на общее имущество многоквартирного дома, а также совершать иные действия, влекущие передачу его доли отдельно от права собственности на помещение, машино-место.\n\n(Статья в редакции  Федерального закона от 21.12.2021 № 430-ФЗ)","article_title":"Статья 290. Общее имущество в многоквартирном доме","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"511b2718987338e32bf77de86f04af98a30514b185f4f5179940cb1252374f57"},{"code_id":"GK_RF","article_number":"292","version_date":"1994-11-30","article_text":"1. Члены семьи собственника, проживающие в принадлежащем ему жилом помещении, имеют право пользования этим помещением на условиях, предусмотренных жилищным законодательством.\n\nДееспособные и ограниченные судом в дееспособности члены семьи собственника, проживающие в принадлежащем ему жилом помещении, несут солидарную с собственником ответственность по обязательствам, вытекающим из пользования жилым помещением. (Дополнение абзацем - Федеральный закон от 15.05.2001 № 54-ФЗ) (В редакции Федерального закона от 24.04.2008 № 49-ФЗ)","article_title":"Статья 292. Права членов семьи собственников жилого помещения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"87a798657071a4a37f9ba7eca66ebc91b118ed5a8e554f17ee52ed3120f18dbe"},{"code_id":"GK_RF","article_number":"293","version_date":"1994-11-30","article_text":"(Статья утратила силу  - Федеральный закон от 21.12.2021 № 430-ФЗ)","article_title":"Статья 293. .","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9bfe03d9d5a725886b26afafd65a088fc3e0b4b25074231cbeed21ad7196abc4"},{"code_id":"GK_RF","article_number":"294","version_date":"1994-11-30","article_text":"Государственное или муниципальное унитарное предприятие, которому имущество принадлежит на праве хозяйственного ведения, владеет, пользуется и распоряжается этим имуществом в пределах, определяемых в соответствии с настоящим Кодексом.","article_title":"Статья 294. Право хозяйственного ведения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f00595906c09f4d93128c8165b36d2075979c76450aca85fed88b70acbfe50f0"},{"code_id":"GK_RF","article_number":"295","version_date":"1994-11-30","article_text":"1. Собственник имущества, находящегося в хозяйственном ведении, в соответствии с законом решает вопросы создания предприятия, определения предмета и целей его деятельности, его реорганизации и ликвидации, назначает директора (руководителя) предприятия, осуществляет контроль за использованием по назначению и сохранностью принадлежащего предприятию имущества.\n\nСобственник имеет право на получение части прибыли от использования имущества, находящегося в хозяйственном ведении предприятия.\n\n2. Предприятие не вправе продавать принадлежащее ему на праве хозяйственного ведения недвижимое имущество, сдавать его в аренду, отдавать в залог, вносить в качестве вклада в уставный (складочный) капитал хозяйственных обществ и товариществ или иным способом распоряжаться этим имуществом без согласия собственника.\n\nОстальным имуществом, принадлежащим предприятию, оно распоряжается самостоятельно, за исключением случаев, установленных законом или иными правовыми актами.","article_title":"Статья 295. Права собственника в отношении имущества, находящегося в хозяйственном ведении","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e70d3fd0996577eef95c0875dd4e0d48d69dbf9cb1f416fb13a718de33beaec1"},{"code_id":"GK_RF","article_number":"296","version_date":"1994-11-30","article_text":"(Статья в редакции Федерального закона от 03.11.2006 № 175-ФЗ)","article_title":"Статья 296. Право оперативного управления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3d057e8db23324ea57825f619dfb1173d7686c044e7c4ae5072043d3f0475ab9"},{"code_id":"GK_RF","article_number":"297","version_date":"1994-11-30","article_text":"1. Казенное предприятие вправе отчуждать или иным способом распоряжаться закрепленным за ним имуществом лишь с согласия собственника этого имущества.\n\nКазенное предприятие самостоятельно реализует производимую им продукцию, если иное не установлено законом или иными правовыми актами.\n\n2. Порядок распределения доходов казенного предприятия определяется собственником его имущества.","article_title":"Статья 297. Распоряжение имуществом казенного предприятия","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"127d0ac22c9e2a21ff7af63010443fa38c7c09f10d6c96f7c93d0c8b61207a9c"},{"code_id":"GK_RF","article_number":"298","version_date":"1994-11-30","article_text":"1. Частное учреждение не вправе отчуждать либо иным способом распоряжаться имуществом, закрепленным за ним собственником или приобретенным этим учреждением за счет средств, выделенных ему собственником на приобретение такого имущества.\n\nЧастное учреждение вправе осуществлять приносящую доходы деятельность, только если такое право предусмотрено в его учредительном документе, при этом доходы, полученные от такой деятельности, и приобретенное за счет этих доходов имущество поступают в самостоятельное распоряжение частного учреждения.\n\n2. Автономное учреждение без согласия собственника не вправе распоряжаться недвижимым имуществом и особо ценным движимым имуществом, закрепленными за ним собственником или приобретенными автономным учреждением за счет средств, выделенных ему собственником на приобретение такого имущества. Остальным имуществом, находящимся у него на праве оперативного управления, автономное учреждение вправе распоряжаться самостоятельно, если иное не установлено законом.\n\nАвтономное учреждение вправе осуществлять приносящую доходы деятельность лишь постольку, поскольку это служит достижению целей, ради которых оно создано, и соответствующую этим целям, при условии, что такая деятельность указана в его учредительных документах. Доходы, полученные от такой деятельности, и приобретенное за счет этих доходов имущество поступают в самостоятельное распоряжение автономного учреждения.\n\n3. Бюджетное учреждение без согласия собственника не вправе распоряжаться особо ценным движимым имуществом, закрепленным за ним собственником или приобретенным бюджетным учреждением за счет средств, выделенных ему собственником на приобретение такого имущества, а также недвижимым имуществом. Остальным имуществом, находящимся у него на праве оперативного управления, бюджетное учреждение вправе распоряжаться самостоятельно, если иное не установлено законом.\n\nБюджетное учреждение вправе осуществлять приносящую доходы деятельность лишь постольку, поскольку это служит достижению целей, ради которых оно создано, и соответствующую этим целям, при условии, что такая деятельность указана в его учредительных документах. Доходы, полученные от такой деятельности, и приобретенное за счет этих доходов имущество поступают в самостоятельное распоряжение бюджетного учреждения.\n\n4. Казенное учреждение не вправе отчуждать либо иным способом распоряжаться имуществом без согласия собственника имущества.\n\nКазенное учреждение может осуществлять приносящую доходы деятельность в соответствии со своими учредительными документами. Доходы, полученные от указанной деятельности, поступают в соответствующий бюджет бюджетной системы Российской Федерации.\n\n(Статья в редакции Федерального закона от 08.05.2010 № 83-ФЗ)","article_title":"Статья 298. Распоряжение имуществом учреждения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2fb6bffe9697634936912993a5278390b05f6a68e43cc9a0aa5287db43b7513d"},{"code_id":"GK_RF","article_number":"299","version_date":"1994-11-30","article_text":"1. Право хозяйственного ведения или право оперативного управления имуществом, в отношении которого собственником принято решение о закреплении за унитарным предприятием или учреждением, возникает у этого предприятия или учреждения с момента передачи имущества, если иное не установлено законом и иными правовыми актами или решением собственника.\n\nесли иное не предусмотрено настоящим Кодексом, прекращаются по основаниям и в порядке, предусмотренным настоящим Кодексом, другими законами и иными правовыми актами для прекращения права собственности, а также в случаях правомерного изъятия имущества у предприятия или учреждения по решению собственника. (В редакции Федерального закона от 31.12.2014 № 499-ФЗ)","article_title":"Статья 299. Приобретение и прекращение права хозяйственного ведения и права оперативного управления","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8b9596ac836213ed2d55bb6248a8ef46b8aeefb7766aeddf3a94bcea1fdc6895"},{"code_id":"GK_RF","article_number":"3","version_date":"1994-11-30","article_text":"1. В соответствии с Конституцией Российской Федерации гражданское законодательство находится в ведении Российской Федерации.\n\n2. Гражданское законодательство состоит из настоящего Кодекса и принятых в соответствии с ним иных федеральных законов (далее - законы), регулирующих отношения, указанные в пунктах 1 и 2 статьи 2 настоящего Кодекса.\n\nНормы гражданского права, содержащиеся в других законах, должны соответствовать настоящему Кодексу.\n\n3. Отношения, указанные в пунктах 1 и 2 статьи 2 настоящего Кодекса, могут регулироваться также указами Президента Российской Федерации, которые не должны противоречить настоящему Кодексу и иным законам.\n\n4. На основании и во исполнение настоящего Кодекса и иных законов, указов Президента Российской Федерации Правительство Российской Федерации вправе принимать постановления, содержащие нормы гражданского права.\n\n5. В случае противоречия указа Президента Российской Федерации или постановления Правительства Российской Федерации настоящему Кодексу или иному закону применяется настоящий Кодекс или соответствующий закон.\n\n6. Действие и применение норм гражданского права, содержащихся в указах Президента Российской Федерации и постановлениях Правительства Российской Федерации (далее - иные правовые акты), определяются правилами настоящей главы.\n\n7. Министерства и иные федеральные органы исполнительной власти могут издавать акты, содержащие нормы гражданского права, в случаях и в пределах, предусмотренных настоящим Кодексом, другими законами и иными правовыми актами.","article_title":"Статья 3. Гражданское законодательство и иные акты, содержащие нормы гражданского права","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ede1b96b5adafe1539c1cd3ee9659305d5e84c9dbbcd9acb2421bbf6249a89db"},{"code_id":"GK_RF","article_number":"30","version_date":"1994-11-30","article_text":"Он вправе самостоятельно совершать мелкие бытовые сделки.\n\nСовершать другие сделки он может лишь с согласия попечителя. Однако такой гражданин самостоятельно несет имущественную ответственность по совершенным им сделкам и за причиненный им вред. Попечитель получает и расходует заработок, пенсию и иные доходы гражданина, ограниченного судом в дееспособности, в интересах подопечного в порядке, предусмотренном статьей 37 настоящего Кодекса. (В редакции Федерального закона от 30.12.2012 № 302-ФЗ)\n\nТакой гражданин совершает сделки, за исключением сделок, предусмотренных подпунктами 1 и 4 пункта 2 статьи 26 настоящего Кодекса, с письменного согласия попечителя. Сделка, совершенная таким гражданином, действительна также при ее последующем письменном одобрении его попечителем. Сделки, предусмотренные подпунктами 1 и 4 пункта 2 статьи 26 настоящего Кодекса, такой гражданин вправе совершать самостоятельно.\n\nГражданин, ограниченный судом в дееспособности по основаниям, предусмотренным настоящим пунктом, может распоряжаться выплачиваемыми на него алиментами, социальной пенсией, возмещением вреда здоровью и в связи со смертью кормильца и иными предоставляемыми на его содержание выплатами с письменного согласия попечителя, за исключением выплат, которые указаны в подпункте 1 пункта 2 статьи 26 настоящего Кодекса и которыми он вправе распоряжаться самостоятельно. Такой гражданин вправе распоряжаться указанными выплатами в течение срока, определенного попечителем. Распоряжение указанными выплатами может быть прекращено до истечения данного срока по решению попечителя.\n\nПри наличии достаточных оснований суд по ходатайству попечителя либо органа опеки и попечительства может ограничить или лишить такого гражданина права самостоятельно распоряжаться своими доходами, указанными в подпункте 1 пункта 2 статьи 26 настоящего Кодекса.\n\nГражданин, дееспособность которого ограничена вследствие психического расстройства, самостоятельно несет имущественную ответственность по сделкам, совершенным им в соответствии с настоящей статьей. За причиненный им вред такой гражданин несет ответственность в соответствии с настоящим Кодексом.\n\n(Пункт в редакции Федерального закона от 30.12.2012 № 302-ФЗ)\n\nЕсли психическое состояние гражданина, который вследствие психического расстройства был в соответствии с пунктом 2 настоящей статьи ограничен в дееспособности, изменилось, суд признает его недееспособным в соответствии со статьей 29 настоящего Кодекса или отменяет ограничение его дееспособности.\n\n(Дополнение пунктом - Федеральный закон от 30.12.2012 № 302-ФЗ)","article_title":"Статья 30. Ограничение дееспособности гражданина","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"7e5823a3012181af7c317ff3325bc4112f5f3dd29be886cd9a8517fc50f8f188"},{"code_id":"GK_RF","article_number":"301","version_date":"1994-11-30","article_text":"Собственник вправе истребовать свое имущество из чужого незаконного владения.","article_title":"Статья 301. Истребование имущества из чужого незаконного владения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"760e6d36f931cf74df6dc2b39603e7169489ab68a75cfbd277038ed6045d286e"},{"code_id":"GK_RF","article_number":"302","version_date":"1994-11-30","article_text":"1. Если имущество возмездно приобретено у лица, которое не имело права его отчуждать, о чем приобретатель не знал и не мог знать (добросовестный приобретатель), то собственник вправе истребовать это имущество от приобретателя в случае, когда имущество утеряно собственником или лицом, которому имущество было передано собственником во владение, либо похищено у того или другого, либо выбыло из их владения иным путем помимо их воли.\n\n2. Если имущество приобретено безвозмездно от лица, которое не имело права его отчуждать, собственник вправе истребовать имущество во всех случаях.\n\n3. Деньги, а также ценные бумаги на предъявителя не могут быть истребованы от добросовестного приобретателя.","article_title":"Статья 302. Истребование имущества от добросовестного приобретателя","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"40843f6c48a91698fca1799140fddc41caa0e86a73b3f273777475cd6b1495d1"},{"code_id":"GK_RF","article_number":"303","version_date":"1994-11-30","article_text":"При истребовании имущества из чужого незаконного владения собственник вправе также потребовать от лица, которое знало или должно было знать, что его владение незаконно (недобросовестный владелец), возврата или возмещения всех доходов, которые это лицо извлекло или должно было извлечь за все время владения; от добросовестного владельца возврата или возмещения всех доходов, которые он извлек или должен был извлечь со времени, когда он узнал или должен был узнать о неправомерности владения или получил повестку по иску собственника о возврате имущества.\n\nВладелец, как добросовестный, так и недобросовестный, в свою очередь вправе требовать от собственника возмещения произведенных им необходимых затрат на имущество с того времени, с которого собственнику причитаются доходы от имущества.\n\nДобросовестный владелец вправе оставить за собой произведенные им улучшения, если они могут быть отделены без повреждения имущества. Если такое отделение улучшений невозможно, добросовестный владелец имеет право требовать возмещения произведенных на улучшение затрат, но не свыше размера увеличения стоимости имущества.","article_title":"Статья 303. Расчеты при возврате имущества из незаконного владения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f6a4d95661dbcdabf675f4381c693cc628db5b02bc22fc0af6646435e61944c1"},{"code_id":"GK_RF","article_number":"304","version_date":"1994-11-30","article_text":"Собственник может требовать устранения всяких нарушений его права, хотя бы эти нарушения и не были соединены с лишением владения.","article_title":"Статья 304. Защита прав собственника от нарушений, не связанных с лишением владения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b6132c391b1331c5f687424508af55d71f1ee4c16d4eef3b70a581605aef4793"},{"code_id":"GK_RF","article_number":"305","version_date":"1994-11-30","article_text":"Права, предусмотренные статьями 301 - 304 настоящего Кодекса, принадлежат также лицу, хотя и не являющемуся собственником, но владеющему имуществом на праве пожизненного наследуемого владения, хозяйственного ведения, оперативного управления либо по иному основанию, предусмотренному законом или договором. Это лицо имеет право на защиту его владения также против собственника.","article_title":"Статья 305. Защита прав владельца, не являющегося собственником","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2417ac2de6497a8ef13b1b1403994c48fab15d25fc8e9fa390cd5cc3c4f4384c"},{"code_id":"GK_RF","article_number":"306","version_date":"1994-11-30","article_text":"В случае принятия Российской Федерацией закона, прекращающего право собственности, убытки, причиненные собственнику в результате принятия этого акта, в том числе стоимость имущества, возмещаются государством. Споры о возмещении убытков разрешаются судом.\n\n(Наименование в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 306. Последствия прекращения права собственности в силу закона","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d6ee8cab2204b5f8f8802139c861f05476d2d7c44f7b5fac11cac0ebcd6edf52"},{"code_id":"GK_RF","article_number":"307","version_date":"1994-11-30","article_text":"1. В силу обязательства одно лицо (должник) обязано совершить в пользу другого лица (кредитора) определенное действие, как то: передать имущество, выполнить работу, оказать услугу, внести вклад в совместную деятельность, уплатить деньги и т.п., либо воздержаться от определенного действия, а кредитор имеет право требовать от должника исполнения его обязанности.\n\n2. Обязательства возникают из договоров и других сделок, вследствие причинения вреда, вследствие неосновательного обогащения, а также из иных оснований, указанных в настоящем Кодексе.\n\n3. При установлении, исполнении обязательства и после его прекращения стороны обязаны действовать добросовестно, учитывая права и законные интересы друг друга, взаимно оказывая необходимое содействие для достижения цели обязательства, а также предоставляя друг другу необходимую информацию.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 307. Понятие обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b75c0309ed5ffdbec44a8da59c63127eec0042b71b75cb2df8b41a67f700a417"},{"code_id":"GK_RF","article_number":"307.1","version_date":"1994-11-30","article_text":"1. К обязательствам, возникшим из договора (договорным обязательствам), общие положения об обязательствах (настоящий подраздел) применяются, если иное не предусмотрено правилами об отдельных видах договоров, содержащимися в настоящем Кодексе и иных законах, а при отсутствии таких специальных правил - общими положениями о договоре (подраздел 2 раздела III).\n\n2. К обязательствам вследствие причинения вреда и к обязательствам вследствие неосновательного обогащения общие положения об обязательствах (настоящий подраздел) применяются, если иное не предусмотрено соответственно правилами глав 59 и 60 настоящего Кодекса или не вытекает из существа соответствующих отношений.\n\n3. Поскольку иное не установлено настоящим Кодексом, иными законами или не вытекает из существа соответствующих отношений, общие положения об обязательствах (настоящий подраздел) применяются к требованиям:\n\n1) возникшим из корпоративных отношений (глава 4);\n\n2) связанным с применением последствий недействительности сделки (параграф 2 главы 9).\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 307.1. Применение общих положений об обязательствах","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"078257f09f70f30d49689ff263a902c049d5cb3321d46f680fb7e6efbaad0096"},{"code_id":"GK_RF","article_number":"308","version_date":"1994-11-30","article_text":"1. В обязательстве в качестве каждой из его сторон - кредитора или должника - могут участвовать одно или одновременно несколько лиц.\n\nНедействительность требований кредитора к одному из лиц, участвующих в обязательстве на стороне должника, равно как и истечение срока исковой давности по требованию к такому лицу, сами по себе не затрагивают его требований к остальным этим лицам.\n\n2. Если каждая из сторон по договору несет обязанность в пользу другой стороны, она считается должником другой стороны в том, что обязана сделать в ее пользу, и одновременно ее кредитором в том, что имеет право от нее требовать.\n\n3. Обязательство не создает обязанностей для лиц, не участвующих в нем в качестве сторон (для третьих лиц).\n\nВ случаях, предусмотренных законом, иными правовыми актами или соглашением сторон, обязательство может создавать для третьих лиц права в отношении одной или обеих сторон обязательства.","article_title":"Статья 308. Стороны обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b41c7fdb186bb7b4eee9fa286a056758dd332a8216aba37ab090ddebc955f384"},{"code_id":"GK_RF","article_number":"308.1","version_date":"1994-11-30","article_text":"1. Альтернативным признается обязательство, по которому должник обязан совершить одно из двух или нескольких действий (воздержаться от совершения действий), выбор между которыми принадлежит должнику, если законом, иными правовыми актами или договором право выбора не предоставлено кредитору или третьему лицу.\n\n2. С момента, когда должник (кредитор, третье лицо) осуществил выбор, обязательство перестает быть альтернативным.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 308.1. Альтернативное обязательство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9406c617fc3d2369d4889983bf25e97d97bd6c517832f45b826bf4db9710ec88"},{"code_id":"GK_RF","article_number":"308.2","version_date":"1994-11-30","article_text":"Факультативным признается обязательство, по которому должнику предоставляется право заменить основное исполнение другим (факультативным) исполнением, предусмотренным условиями обязательства. В случае, если должник осуществляет свое право на замену исполнения, предусмотренного условиями обязательства, кредитор обязан принять от должника соответствующее исполнение по обязательству.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 308.2. Факультативное обязательство","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"b9673a90ae6df171592f064710452b5fbdea2dad12e85246eeff2fce33c3a778"},{"code_id":"GK_RF","article_number":"308.3","version_date":"1994-11-30","article_text":"1. В случае неисполнения должником обязательства кредитор вправе требовать по суду исполнения обязательства в натуре, если иное не предусмотрено настоящим Кодексом, иными законами или договором либо не вытекает из существа обязательства. Суд по требованию кредитора вправе присудить в его пользу денежную сумму (пункт 1 статьи 330) на случай неисполнения указанного судебного акта в размере, определяемом судом на основе принципов справедливости, соразмерности и недопустимости извлечения выгоды из незаконного или недобросовестного поведения (пункт 4 статьи 1).\n\n2. Защита кредитором своих прав в соответствии с пунктом 1 настоящей статьи не освобождает должника от ответственности за неисполнение или ненадлежащее исполнение обязательства (глава 25).\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 308.3. Защита прав кредитора по обязательству","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ecd57eb8bbf8b5a1ac0e56c219313aa7d9e7835125adf94188444a7028536313"},{"code_id":"GK_RF","article_number":"309","version_date":"1994-11-30","article_text":"Обязательства должны исполняться надлежащим образом в соответствии с условиями обязательства и требованиями закона, иных правовых актов, а при отсутствии таких условий и требований - в соответствии с обычаями или иными обычно предъявляемыми требованиями. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)\n\nУсловиями сделки может быть предусмотрено исполнение ее сторонами возникающих из нее обязательств при наступлении определенных обстоятельств без направленного на исполнение обязательства отдельно выраженного дополнительного волеизъявления его сторон путем применения информационных технологий, определенных условиями сделки. (Дополнение частью - Федеральный закон от 18.03.2019 № 34-ФЗ)","article_title":"Статья 309. Общие положения","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3c4f88c53ca84d221b69a43bc785afdb330ff769e5d0372727bc62f217d8e3fa"},{"code_id":"GK_RF","article_number":"309.1","version_date":"1994-11-30","article_text":"1. Между кредиторами одного должника по однородным обязательствам может быть заключено соглашение о порядке удовлетворения их требований к должнику, в том числе об очередности их удовлетворения и о непропорциональности распределения исполнения. Стороны указанного соглашения обязаны не совершать действия, направленные на получение исполнения от должника, в нарушение условий указанного соглашения.\n\n2. Исполнение, полученное от должника одним из кредиторов в нарушение условий соглашения между кредиторами о порядке удовлетворения их требований к должнику, подлежит передаче кредитору по другому обязательству в соответствии с условиями указанного соглашения. К кредитору, который передал полученное от должника исполнение другому кредитору, переходит требование последнего к должнику в соответствующей части.\n\n3. Соглашение кредиторов о порядке удовлетворения их требований к должнику не создает обязанностей для лиц, не участвующих в нем в качестве сторон, в том числе для должника (статья 308).\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 309.1. Соглашение кредиторов о порядке удовлетворения их требований к должнику","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"38009aec83e748d5e0360ad59447c1153371a0257da517f890012fae217992e3"},{"code_id":"GK_RF","article_number":"309.2","version_date":"1994-11-30","article_text":"Должник несет расходы на исполнение обязательства, если иное не предусмотрено законом, иными правовыми актами или договором либо не вытекает из существа обязательства, обычаев или других обычно предъявляемых требований.\n\n(Дополнение статьей - Федеральный закон от 08.03.2015 № 42-ФЗ)","article_title":"Статья 309.2. Расходы на исполнение обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"39a346331cc17941267873b527f06ace561416fb365eb639320dd7a2ca7c4e24"},{"code_id":"GK_RF","article_number":"310","version_date":"1994-11-30","article_text":"1. Односторонний отказ от исполнения обязательства и одностороннее изменение его условий не допускаются, за исключением случаев, предусмотренных настоящим Кодексом, другими законами или иными правовыми актами.\n\n2. Одностороннее изменение условий обязательства, связанного с осуществлением всеми его сторонами предпринимательской деятельности, или односторонний отказ от исполнения этого обязательства допускается в случаях, предусмотренных настоящим Кодексом, другими законами, иными правовыми актами или договором.\n\nВ случае, если исполнение обязательства связано с осуществлением предпринимательской деятельности не всеми его сторонами, право на одностороннее изменение его условий или отказ от исполнения обязательства может быть предоставлено договором лишь стороне, не осуществляющей предпринимательской деятельности, за исключением случаев, когда законом или иным правовым актом предусмотрена возможность предоставления договором такого права другой стороне.\n\n3. Предусмотренное настоящим Кодексом, другим законом, иным правовым актом или договором право на односторонний отказ от исполнения обязательства, связанного с осуществлением его сторонами предпринимательской деятельности, или на одностороннее изменение условий такого обязательства может быть обусловлено по соглашению сторон необходимостью выплаты определенной денежной суммы другой стороне обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 310. Недопустимость одностороннего отказа от исполнения обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3cecd6e7538c8a501213e116bec102fcfe238e3c456fdd976e80bc854227e23c"},{"code_id":"GK_RF","article_number":"311","version_date":"1994-11-30","article_text":"Кредитор вправе не принимать исполнения обязательства по частям, если иное не предусмотрено законом, иными правовыми актами, условиями обязательства и не вытекает из обычаев или существа обязательства. (В редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 311. Исполнение обязательства по частям","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"356bd0582672b100d6016efac695ae3319ee23e7e7c7111b4c4db99fd5fdfe14"},{"code_id":"GK_RF","article_number":"313","version_date":"1994-11-30","article_text":"1. Кредитор обязан принять исполнение, предложенное за должника третьим лицом, если исполнение обязательства возложено должником на указанное третье лицо.\n\n2. Если должник не возлагал исполнение обязательства на третье лицо, кредитор обязан принять исполнение, предложенное за должника таким третьим лицом, в следующих случаях:\n\n1) должником допущена просрочка исполнения денежного обязательства;\n\n2) такое третье лицо подвергается опасности утратить свое право на имущество должника вследствие обращения взыскания на это имущество.\n\n3. Кредитор не обязан принимать исполнение, предложенное за должника третьим лицом, если из закона, иных правовых актов, условий обязательства или его существа вытекает обязанность должника исполнить обязательство лично.\n\n4. В случаях, если в соответствии с настоящей статьей допускается исполнение обязательства третьим лицом, оно вправе исполнить обязательство также посредством внесения долга в депозит нотариуса или произвести зачет с соблюдением правил, установленных настоящим Кодексом для должника.\n\n5. К третьему лицу, исполнившему обязательство должника, переходят права кредитора по обязательству в соответствии со статьей 387 настоящего Кодекса. Если права кредитора по обязательству перешли к третьему лицу в части, они не могут быть использованы им в ущерб кредитору, в частности такие права не имеют преимуществ при их удовлетворении за счет обеспечивающего обязательства или при недостаточности у должника средств для удовлетворения требования в полном объеме.\n\n6. Если третье лицо исполнило обязанность должника, не являющуюся денежной, оно несет перед кредитором установленную для данного обязательства ответственность за недостатки исполнения вместо должника.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 313. Исполнение обязательства третьим лицом","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"df503bbccc67fc5143be55717f2eced6d8a4d304e3c6745ee9a696e76ea706a0"},{"code_id":"GK_RF","article_number":"314","version_date":"1994-11-30","article_text":"1. Если обязательство предусматривает или позволяет определить день его исполнения либо период, в течение которого оно должно быть исполнено (в том числе в случае, если этот период исчисляется с момента исполнения обязанностей другой стороной или наступления иных обстоятельств, предусмотренных законом или договором), обязательство подлежит исполнению в этот день или соответственно в любой момент в пределах такого периода.\n\n2. В случаях, когда обязательство не предусматривает срок его исполнения и не содержит условия, позволяющие определить этот срок, а равно и в случаях, когда срок исполнения обязательства определен моментом востребования, обязательство должно быть исполнено в течение семи дней со дня предъявления кредитором требования о его исполнении, если обязанность исполнения в другой срок не предусмотрена законом, иными правовыми актами, условиями обязательства или не вытекает из обычаев либо существа обязательства. При непредъявлении кредитором в разумный срок требования об исполнении такого обязательства должник вправе потребовать от кредитора принять исполнение, если иное не предусмотрено законом, иными правовыми актами, условиями обязательства или не явствует из обычаев либо существа обязательства.\n\n(Статья в редакции Федерального закона от 08.03.2015 № 42-ФЗ)","article_title":"Статья 314. Срок исполнения обязательства","amendment_eo_number":"51-ФЗ","amendment_date":"1994-11-30","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"64ddc5d99e4a5bb6df6de6e8d0318c39a4952b664e9a39f01ba34190e782c5db"}]$law7v008$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text)) insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at) select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
    commit;
